#!/usr/bin/env node
// Builds every lab's start/ and solution/ projects FROM THE STARTERS — never from a hand-kept
// template. A lab state is: a project generated by the New Project generator (the same engine the
// IntelliJ / VS Code wizards and the Maven archetype apply to starters/), plus the step overlays of
// tools/steps/<language>/<NN>/ copied over it, in order.
//
//   node workshop/tools/build-labs.mjs            # (re)write workshop/labs/**/{start,solution}
//   node workshop/tools/build-labs.mjs --check    # build into a temp dir and fail if the committed labs differ
//
// The Mateu version is the one the starters pin (starters/spring-mvc/pom.xml <mateu.version>), which
// scripts/bump-example-version.sh moves after each release — together with the copies under workshop/.
// Needs the VS Code extension compiled once: (cd frontend/app/vscode-extension && npm ci && npm run compile).
import { execFileSync } from 'node:child_process'
import { cpSync, existsSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync, mkdirSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join, relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const workshop = resolve(here, '..')
const repo = resolve(workshop, '..')
const check = process.argv.includes('--check')

const pom = readFileSync(join(repo, 'starters/spring-mvc/pom.xml'), 'utf8')
const version = pom.match(/<mateu\.version>([^<]+)<\/mateu\.version>/)[1]
const nuget = version.replace(/^(\d+)\.(\d+)-/, '$1.$2.0-')
const pypi = version
  .replace(/^(\d+)\.(\d+)-([a-z]+)\.(\d+)$/, '$1.$2.0$3$4')
  .replace('alpha', 'a')
  .replace('beta', 'b')

const cli = join(repo, 'frontend/app/vscode-extension/scripts/new-project.mjs')
if (!existsSync(join(repo, 'frontend/app/vscode-extension/out/newProject.js'))) {
  console.error('Compile the generator first: (cd frontend/app/vscode-extension && npm ci && npm run compile)')
  process.exit(2)
}

const work = mkdtempSync(join(tmpdir(), 'mateu-workshop-'))
const out = check ? join(work, 'labs') : join(workshop, 'labs')

function generate(name, args) {
  const dir = join(work, 'gen', name)
  execFileSync('node', [cli, ...args, '--version', version, '--out', dir], { stdio: ['ignore', 'ignore', 'inherit'] })
  return dir
}

const code = ['--group', 'com.example', '--artifact', 'workshop', '--package', 'com.example.workshop']
const bases = {
  java: generate('java', ['--runtime', 'spring-mvc', ...code]),
  'java-redwood': generate('java-redwood', ['--runtime', 'spring-mvc', '--renderer', 'redwood', ...code]),
  dotnet: generate('dotnet', ['--runtime', 'dotnet', ...code]),
  python: generate('python', ['--runtime', 'python', ...code]),
  static: generate('static', ['--authoring', 'static', '--template', 'listing', '--group', 'com.example', '--artifact', 'workshop-ui']),
}

const TEXT = /\.(java|cs|csproj|py|txt|xml|properties|ya?ml|json|md|sh|mjs|toml)$/

function substitute(dir) {
  for (const f of walk(dir)) {
    if (!TEXT.test(f)) continue
    const s = readFileSync(f, 'utf8')
    const t = s.replaceAll('@MATEU_VERSION@', version).replaceAll('@NUGET_VERSION@', nuget).replaceAll('@PYPI_VERSION@', pypi)
    if (t !== s) writeFileSync(f, t)
  }
}

function walk(dir) {
  return readdirSync(dir).flatMap((n) => {
    const p = join(dir, n)
    return statSync(p).isDirectory() ? walk(p) : [p]
  })
}

/** base + the overlays of steps, in order. */
function state(base, lang, steps) {
  const dir = mkdtempSync(join(work, 'state-'))
  cpSync(bases[base], dir, { recursive: true })
  for (const step of steps) {
    const overlay = join(here, 'steps', lang, step)
    if (!existsSync(overlay)) throw new Error(`missing overlay ${relative(repo, overlay)}`)
    cpSync(overlay, dir, { recursive: true })
  }
  substitute(dir)
  return dir
}

// lab → language → [start, solution], each [base, overlays]
const LABS = {
  '01-first-app': {
    java: [['java', []], ['java', ['01']]],
    dotnet: [['dotnet', []], ['dotnet', ['01']]],
    python: [['python', []], ['python', ['01']]],
  },
  '02-renderers': {
    // only Java changes code: the renderer is a dependency. C# and Python point MATEU_UI at a jar.
    java: [['java', ['01']], ['java-redwood', ['01']]],
  },
  '03-test-like-a-user': {
    java: [['java', ['01']], ['java', ['01', '03']]],
    dotnet: [['dotnet', ['01']], ['dotnet', ['01', '03']]],
    python: [['python', ['01']], ['python', ['01', '03']]],
  },
  '04-ui-as-data': {
    shared: [['static', []], ['static', ['04']]],
  },
  '05-ai-agents': {
    java: [['java', ['01', '03']], ['java', ['01', '03', '05']]],
    dotnet: [['dotnet', ['01', '03']], ['dotnet', ['01', '03', '05']]],
    python: [['python', ['01', '03']], ['python', ['01', '03', '05']]],
  },
  '06-sign-in': {
    java: [['java', ['01', '03']], ['java', ['01', '03', '06']]],
    dotnet: [['dotnet', ['01', '03']], ['dotnet', ['01', '03', '06']]],
    python: [['python', ['01', '03']], ['python', ['01', '03', '06']]],
  },
}

for (const [lab, langs] of Object.entries(LABS)) {
  for (const [lang, [start, solution]] of Object.entries(langs)) {
    const overlayLang = lang === 'shared' ? 'shared' : lang
    for (const [kind, [base, steps]] of [['start', start], ['solution', solution]]) {
      const target = lang === 'shared' ? join(out, lab, kind) : join(out, lab, lang, kind)
      rmSync(target, { recursive: true, force: true })
      mkdirSync(dirname(target), { recursive: true })
      cpSync(state(base, overlayLang, steps), target, { recursive: true })
    }
  }
}

if (check) {
  const committed = join(workshop, 'labs')
  const diffs = []
  for (const [lab, langs] of Object.entries(LABS)) {
    // a shared lab's folder also holds its guides and images: compare only the generated projects
    const rels = Object.keys(langs).flatMap((lang) =>
      lang === 'shared' ? [join(lab, 'start'), join(lab, 'solution')] : [join(lab, lang)])
    for (const rel of rels) {
      try {
        execFileSync('diff', ['-r', '-x', 'target', '-x', 'bin', '-x', 'obj', '-x', '__pycache__', '-x', '.pytest_cache',
          '-x', '.venv', '-x', 'node_modules', join(out, rel), join(committed, rel)], { stdio: 'pipe' })
      } catch (e) {
        diffs.push(`${rel}:\n${e.stdout}`)
      }
    }
  }
  rmSync(work, { recursive: true, force: true })
  if (diffs.length) {
    console.error(`The committed labs differ from what the starters generate (Mateu ${version}).\n` +
      'Run node workshop/tools/build-labs.mjs and commit the result.\n\n' + diffs.join('\n'))
    process.exit(1)
  }
  console.log(`labs up to date (Mateu ${version})`)
} else {
  rmSync(work, { recursive: true, force: true })
  console.log(`labs written (Mateu ${version}, NuGet ${nuget}, PyPI ${pypi})`)
}
